// Prepare & Classify Error
// 1) Extracts execution context from the error trigger (record fields)
// 2) Classifies error type/severity/retryability, LLM cost estimate, auto-retry registry

const execution = $json.execution || {};
const workflow = $json.workflow || {};
const error = $json.error || {};

// ====== 1) Prepare record ======

// Extract failing node name from multiple possible locations
const failedNode = execution.lastNodeExecuted ||
                   error.node ||
                   error.nodeName ||
                   (error.context && error.context.nodeName) ||
                   'unknown';

// Extract error message from multiple possible locations
let rawErrorMsg = error.message;
if (!rawErrorMsg) {
  rawErrorMsg = error.description || error.reason || error.cause ||
                error.details || error.errorMessage;
}
// If still no message but error has a name that's descriptive, use it
if (!rawErrorMsg && error.name && error.name !== 'Error' && error.name !== 'NodeOperationError') {
  rawErrorMsg = error.name;
}
// Last resort: stringify, but check if it's actually useful
if (!rawErrorMsg) {
  const stringified = JSON.stringify(error);
  if (stringified && stringified !== '{}' && stringified !== 'null' && stringified.length > 2) {
    rawErrorMsg = stringified;
  }
}
// Final fallback with specific hint
if (!rawErrorMsg) {
  rawErrorMsg = 'LLM output did not match required schema - check model response format';
}

// Extract retry_input - data needed to restart workflow from scratch
let retryInputData = {};
const runData = execution.data?.resultData?.runData || {};
const nodesToCheck = ['Set File ID', 'Gmail', 'Gmail Trigger', 'Clean Email', 'Manual Trigger'];
for (const nodeName of nodesToCheck) {
  const nodeData = runData[nodeName]?.[0]?.data?.main?.[0]?.[0]?.json;
  if (nodeData) {
    if (nodeData.email_ID) retryInputData.email_ID = nodeData.email_ID;
    if (nodeData.id && !retryInputData.email_ID) retryInputData.email_ID = nodeData.id;
    if (nodeData.messageId) retryInputData.messageId = nodeData.messageId;
    break; // Found data, stop searching
  }
}

// ====== Extract attachment count for LLM cost estimation ======
let attachmentCount = 0;

// Strategy 1: Check Gmail node for binary attachments
const gmailNodeData = runData['Gmail']?.[0]?.data?.main?.[0]?.[0];
if (gmailNodeData?.binary) {
  attachmentCount = Object.keys(gmailNodeData.binary).length;
}
// Strategy 2: Check Gmail Trigger node
if (attachmentCount === 0) {
  const gmailTriggerData = runData['Gmail Trigger']?.[0]?.data?.main?.[0]?.[0];
  if (gmailTriggerData?.binary) {
    attachmentCount = Object.keys(gmailTriggerData.binary).length;
  }
}
// Strategy 3: Check "sp" (Split Out) node output count
if (attachmentCount === 0) {
  const spNodeData = runData['sp'];
  if (spNodeData && spNodeData[0]?.data?.main?.[0]) {
    attachmentCount = spNodeData[0].data.main[0].length;
  }
}
// Strategy 4: Check Clean Email object for attachmentNames
if (attachmentCount === 0) {
  const cleanEmailData = runData['Clean Email object']?.[0]?.data?.main?.[0]?.[0]?.json;
  if (cleanEmailData?.data?.[0]?.attachmentNames) {
    attachmentCount = cleanEmailData.data[0].attachmentNames.length;
  }
}
// Default to 1 if we couldn't determine (conservative estimate)
if (attachmentCount === 0) {
  attachmentCount = 1;
}

const record = {
  timestamp: new Date().toISOString(),
  workflow_id: workflow.id || 'unknown',
  workflow_name: workflow.name || 'unknown',
  execution_id: execution.retryOf || execution.id || 'unknown',
  execution_mode: execution.mode || 'unknown',
  failed_node: failedNode,
  retry_of: execution.retryOf || '',
  error_message: rawErrorMsg.substring(0, 500),
  error_stack: (error.stack || '').substring(0, 1000),
  error_name: error.name || 'Error',
  started_at: execution.startedAt || '',
  status: 'pending_retry',
  retry_count: 0,
  retry_input: JSON.stringify(retryInputData),
  attachment_count: attachmentCount
};

// ====== 2) Classify ======

const errorMsg = record.error_message.toLowerCase();
const errorMsgOriginal = record.error_message;
const errorName = record.error_name.toLowerCase();
const workflowName = record.workflow_name;

// ====== Auto-Retry Registry ======
// Workflows that support automatic retry on rate limits
const AUTO_RETRY_REGISTRY = [
  'smart-folder2table',
  'any-file2json-converter',
  // Add more as needed
];

const canAutoRetry = AUTO_RETRY_REGISTRY.some(name =>
  workflowName.toLowerCase().includes(name.toLowerCase())
);

let errorType = 'unknown';
let severity = 'medium';
let isRetryable = false;
let suggestedAction = 'manual_review';

// Auth errors (401, 403, credential issues)
if (errorMsg.includes('401') || errorMsg.includes('403') ||
    errorMsg.includes('unauthorized') || errorMsg.includes('forbidden') ||
    errorMsg.includes('credential') || errorMsg.includes('token expired') ||
    errorMsg.includes('invalid_grant') || errorMsg.includes('authentication')) {
  errorType = 'auth_error';
  severity = 'critical';
  suggestedAction = 'refresh_credentials';
  isRetryable = false;
}
// Rate limits (429)
else if (errorMsg.includes('429') || errorMsg.includes('rate limit') ||
         errorMsg.includes('too many requests') || errorMsg.includes('quota') ||
         errorMsg.includes('throttl')) {
  errorType = 'rate_limit';
  severity = 'high';
  suggestedAction = 'wait_and_retry';
  isRetryable = true;
}
// Network/timeout errors
// 'timed out' and 'service unavailable' were added 2026-08-12 after a corpus run:
// they are the two most common failures on the instance (93 and 6 executions) and
// BOTH were falling through to 'unknown'/not-retryable. n8n's task-runner timeout
// reads "task request timed out after 60 seconds" — no 'timeout', no code — and a
// provider 503 often arrives as the words rather than the number. Misclassifying
// them costs twice: the resolver skips a retry that would have worked, and the
// upkeep digest reports an infrastructure incident as a code defect.
else if (errorMsg.includes('timeout') || errorMsg.includes('timed out') ||
         errorMsg.includes('etimedout') ||
         errorMsg.includes('econnrefused') || errorMsg.includes('econnreset') ||
         errorMsg.includes('network') || errorMsg.includes('enotfound') ||
         errorMsg.includes('socket hang up') || errorMsg.includes('502') ||
         errorMsg.includes('503') || errorMsg.includes('504') ||
         errorMsg.includes('service unavailable')) {
  errorType = 'network_error';
  severity = 'high';
  suggestedAction = 'retry_with_backoff';
  isRetryable = true;
}
// LLM Schema errors (specific pattern - retryable because LLMs are non-deterministic)
else if (errorMsg.includes('llm output did not match required schema')) {
  errorType = 'llm_schema_error';
  severity = 'high';
  suggestedAction = 'auto_retry_8h';
  isRetryable = true;
}
// Parse errors (JSON, schema) - general case, NOT retryable
else if (errorMsg.includes('json') || errorMsg.includes('parse') ||
         errorMsg.includes('unexpected token') || errorMsg.includes('schema') ||
         errorMsg.includes('syntax error') || errorName.includes('syntaxerror')) {
  errorType = 'parse_error';
  severity = 'medium';
  suggestedAction = 'check_llm_output';
  isRetryable = false;
}
// Validation errors
else if (errorMsg.includes('required') || errorMsg.includes('missing') ||
         errorMsg.includes('invalid') || errorMsg.includes('validation') ||
         errorMsg.includes('not found') || errorMsg.includes('does not exist')) {
  errorType = 'validation_error';
  severity = 'medium';
  suggestedAction = 'check_input_data';
  isRetryable = false;
}
// Resource errors
else if (errorMsg.includes('memory') || errorMsg.includes('disk') ||
         errorMsg.includes('storage') || errorMsg.includes('out of space')) {
  errorType = 'resource_error';
  severity = 'critical';
  suggestedAction = 'check_resources';
  isRetryable = false;
}

// ====== LLM Cost Estimation by Provider ======
// Rate limits are per API provider, so we track them separately:
// - Groq: 5 req/min (bottleneck causing 429 errors)
// - Google Gemini: Separate limit for OCR (not typically the bottleneck)
const LLM_COST_BY_NODE = {
  // Early failures - most work remaining
  'Gmail Trigger':           { groq_base: 1, groq_per_att: 1, google_per_att: 1 },
  'Clean Email object':      { groq_base: 1, groq_per_att: 1, google_per_att: 1 },

  // Classification stage (Groq)
  'subject-classifier-LM':   { groq_base: 1, groq_per_att: 1, google_per_att: 0 },

  // Attachment processing stage
  'any-file2json-converter': { groq_base: 0, groq_per_att: 1, google_per_att: 1 },
  'Create Attachment Profile':{ groq_base: 0, groq_per_att: 1, google_per_att: 1 },

  // Invoice extraction stage (Groq only)
  'Accountant-concierge-LM': { groq_base: 0, groq_per_att: 1, google_per_att: 0 },

  // smart-table-fill (Groq, batched) - 4 batches typical
  'Extract Data from String':{ groq_base: 0, groq_per_att: 4, google_per_att: 0 },
  "Call 'smart-table-fill'": { groq_base: 0, groq_per_att: 4, google_per_att: 0 },
  'smart-table-fill':        { groq_base: 0, groq_per_att: 4, google_per_att: 0 },

  // Default for unknown nodes
  '_default':                { groq_base: 1, groq_per_att: 1, google_per_att: 1 }
};

const cost = LLM_COST_BY_NODE[record.failed_node] || LLM_COST_BY_NODE['_default'];
const expected_groq_requests = cost.groq_base + (attachmentCount * cost.groq_per_att);
const expected_google_requests = attachmentCount * cost.google_per_att;

// Package LLM cost estimate as single JSON field
// Different workflows have different cost structures, so keep as flexible package
const llmCostEstimate = {
  attachment_count: attachmentCount,
  groq: expected_groq_requests,
  google: expected_google_requests
};

// ====== Extract Retry Timing for Rate Limits ======
let retryAfterSeconds = 60; // default
if (errorType === 'rate_limit') {
  // Pattern: "retry in 55.251598518s" or "retry in 55 seconds"
  const retryMatch = errorMsgOriginal.match(/retry in (\d+(?:\.\d+)?)\s*s/i);
  if (retryMatch) {
    retryAfterSeconds = Math.ceil(parseFloat(retryMatch[1]));
  }
}

// ====== 3) Fingerprint ======
// A failure that repeats with an identical signature is a defect, not an incident.
// This is what makes "the same bug again" detectable at all. NOTHING READS IT YET —
// stage 1 of docs/upkeep-tasks-spec.md. Append-only by design, so it can never race the
// way an occurrence counter would.
//
// Deliberately not require('crypto'): Node builtins are gated behind
// NODE_FUNCTION_ALLOW_BUILTIN, which is not set on this instance, and it would throw
// at runtime rather than at edit time. FNV-1a is enough for a few dozen signatures.
const fnv1a = (s) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(36);
};

// Strip everything that varies between two occurrences of the SAME bug, so they hash
// alike. Both directions fail: too aggressive merges distinct bugs into one useless
// row; too loose fragments one bug across many fingerprints so it never reaches a
// threshold. Fragmentation is the more dangerous half, because it is silent.
// Order matters — every placeholder below is digit-free so the \\d+ pass cannot eat it.
const errorSignature = errorMsgOriginal
  .replace(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi, '<uuid>')
  .replace(/[A-Za-z]:\\\\[^\s"')]+|\/(?:tmp|var|home|usr|root)\/[^\s"')]+/g, '<path>')
  .replace(/"[^"]*"/g, '<str>')
  .replace(/\b[0-9a-f]{8,}\b/gi, '<hex>')
  .replace(/\d+/g, '<n>')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase()
  .substring(0, 200);

// workflow_id and node name are in the hash so an identical generic message in two
// workflows stays two bugs.
const fingerprint = fnv1a(record.workflow_id + ' ' + record.failed_node + ' ' + errorSignature);

return [{
  json: {
    ...record,
    error_type: errorType,
    severity: severity,
    is_retryable: isRetryable,
    suggested_action: suggestedAction,
    retry_params: JSON.stringify(llmCostEstimate),
    can_auto_retry: canAutoRetry,
    retry_after_seconds: retryAfterSeconds,
    fingerprint: fingerprint,
    error_signature: errorSignature.substring(0, 120)
  }
}];

// Format Telegram Alert with Severity Emoji
// Outputs FULL message (no truncation) - chunking handled downstream
// Includes LLM cost estimates for rate-limit awareness

const esc = (s) => String(s).replace(/_/g, '\\_');

const severityEmoji = {
  critical: '\uD83D\uDD34', // Red circle
  high: '\uD83D\uDFE0',     // Orange circle
  medium: '\uD83D\uDFE1',   // Yellow circle
  low: '\uD83D\uDFE2'       // Green circle
};

const emoji = severityEmoji[$json.severity] || '\u26AA'; // White circle default

// Parse LLM cost estimate JSON
const llmCost = JSON.parse($json.retry_params || '{}');

// Build full message with failed node prominently displayed
// Added attachment count and LLM estimates for rate limit visibility
const msg = `${emoji} ${esc($json.error_type).toUpperCase()}
\u274C Workflow: ${esc($json.workflow_name)}
\uD83D\uDCCD Node: ${esc($json.failed_node || 'unknown')}
---
Error: ${esc($json.error_message)}
---
Execution: ${$json.execution_id}
Severity: ${$json.severity}
Retryable: ${$json.is_retryable ? 'Yes' : 'No'}
Action: ${esc($json.suggested_action)}
Attachments: ${llmCost.attachment_count || 0}
LLM calls: Groq=${llmCost.groq || 0} | Google=${llmCost.google || 0}
Stack: ${esc($json.error_stack || 'N/A')}`;

return [{
  json: {
    fullMessage: msg
  }
}];

// Split Long Message into Chunks
// Telegram max message length is ~4096 chars, using 4000 to be safe

const message = $json.fullMessage || 'No error message';
const maxLength = 4000;
const chunks = [];

for (let i = 0; i < message.length; i += maxLength) {
  chunks.push(message.substring(i, i + maxLength));
}

return chunks.map((chunk, idx) => ({
  json: {
    chunk: chunk,
    part: idx + 1,
    total: chunks.length
  }
}));

