// Extract Config for Execute Workflow retry
// Gets original Config values from failed execution's runData
const execution = $('Error Trigger').first().json.execution || {};
const runData = execution.data?.resultData?.runData || {};

// Extract Config node output from smart-folder2table
const configData = runData['Config']?.[0]?.data?.main?.[0]?.[0]?.json || {};

return [{
  json: {
    // Pass original config values
    folder_id: configData.folder_id || '',
    spreadsheet_id: configData.spreadsheet_id || '',
    data_sheet_name: configData.data_sheet_name || 'Sheet1',
    source_file_column: configData.source_file_column || 'source_file',
    match_column: configData.match_column || 'source_file',
    batch_size: configData.batch_size || 10,
    schema_sheet_name: configData.schema_sheet_name || 'Description_hig7f6',
    // Add new rate limit param from error classification
    rate_limit_wait_seconds: $('Prepare & Classify Error').first().json.retry_after_seconds || 60
  }
}];

